 [Serializable] public sealed class SavedSurface {
  public List<Expedition> expeditions=new List<Expedition>();public int ammo=24;public float pulse;
  public bool Validate(){if(expeditions==null||expeditions.Count>128||ammo<0||ammo>24||!VoyagerState.Finite(pulse))return false;var keys=new HashSet<string>();foreach(var e in expeditions){if(e==null||string.IsNullOrEmpty(e.key)||!keys.Add(e.key)||e.sites==null||e.sites.Count>12||e.foes==null||e.foes.Count>40||!VoyagerState.Finite(e.relayHealth))return false;foreach(var f in e.foes)if(f==null||f.kind<0||f.kind>2||f.burst<0||f.burst>3||!VoyagerState.Finite(f.burstClock)||!VoyagerState.Finite(f.hp)||!VoyagerState.Finite(f.local.x)||!VoyagerState.Finite(f.local.y)||!VoyagerState.Finite(f.local.z))return false;}return true;}
