 public SavedSurface Capture(){return new SavedSurface{expeditions=new List<Expedition>(records.Values),ammo=Ammo,pulse=PulseCooldown};}
 public void Restore(SavedSurface saved){ResetAll();foreach(var e in saved.expeditions)records[e.key]=e;Ammo=saved.ammo;PulseCooldown=saved.pulse;Scripted=false;}
