 public void Initialize(DefenseGame owner,PlanetExpedition expedition,Camera cam){game=owner;ground=expedition;camera=cam;art=new SurfaceArt();rifle=art.Rifle(ground.Crew);rifle.gameObject.SetActive(false);flora=gameObject.AddComponent<SurfaceFlora>();flora.Initialize(ground,art);gameObject.AddComponent<SurfaceScenery>().Initialize(ground,art);settlement=gameObject.AddComponent<SurfaceSettlement>();settlement.Initialize(ground,art);audioSource=gameObject.AddComponent<AudioSource>();audioSource.volume=.22f;if(FindFirstObjectByType<AudioListener>()==null)camera.gameObject.AddComponent<AudioListener>();laserClip=Tone("Carbine discharge",900,100,.11f,.24f);hitClip=Tone("Chitin impact",190,55,.12f,.35f);pulseClip=Tone("Suit shockwave",90,28,.5f,.6f);alertClip=Tone("Alien warning",140,64,.35f,.3f);}
 AudioClip Tone(string name,float start,float end,float duration,float noise){int n=(int)(22050*duration);var a=new float[n];var random=new System.Random(131);float phase=0;for(int i=0;i<n;i++){float t=i/(float)n;phase+=Mathf.Lerp(start,end,t)*Mathf.PI*2/22050;a[i]=(Mathf.Sin(phase)*(.7f)+((float)random.NextDouble()*2-1)*noise)*Mathf.Pow(1-t,2)*Mathf.Min(1,t*30);}var clip=AudioClip.Create(name,n,1,22050,false);clip.SetData(a,0);return clip;}
 void Sound(AudioClip clip,float volume=1){if(audioSource!=null)audioSource.PlayOneShot(clip,volume*game.EffectsVolume);}
 public Vector3 World(Site site){return Planet.body.P+site.local;}
 public Vector3 World(Foe foe){return Planet.body.P+foe.local;}
 public Vector3 Up(Vector3 p){return (p-Planet.body.P).normalized;}
 public Vector3 GroundPoint(Vector3 p,float clearance=0){Vector3 d=(p-Planet.body.P).normalized;Vector3 q=Planet.body.P+d*((float)Planet.body.radius+PlanetExpedition.Height(d,Planet.body.seed,Planet.body.radius)+clearance);float alt=ground.Alt(q);if(alt<clearance)q+=d*(clearance-alt);return q;}
 Vector3 Offset(Vector3 anchor,Vector3 tangent,float x,float z){Vector3 up=Up(anchor),side=Vector3.Cross(up,tangent).normalized;return GroundPoint(anchor+side*x+tangent*z);}
 Site AddSite(string kind,Vector3 p){Vector3 n=(p-Planet.body.P).normalized;var s=new Site{kind=kind,local=n*((float)Planet.body.radius+PlanetExpedition.Height(n,Planet.body.seed,Planet.body.radius))};Current.sites.Add(s);return s;}
 // Keep approaches and objective-to-objective walking corridors free of large generated props.
 public bool ReservedApproach(PlanetExpedition.Planet p,Vector3 local,float radius){
  if(p==null||!records.TryGetValue(p.key,out var e))return false;
  if(Vector3.Distance(local,e.anchor)<8+radius)return true;
  foreach(var site in e.sites){if(DefenseGame.SegmentDistance(local,e.anchor,site.local)<2.6f+radius)return true;foreach(var other in e.sites)if(site!=other&&DefenseGame.SegmentDistance(local,site.local,other.local)<2.6f+radius)return true;}
  return false;
 }
 public void Sync(){
  if(ground.OnFoot){var p=ground.Nearest(ground.Focus);if(p==null)return;if(!wasOnFoot||Planet!=p){Detach();Planet=p;if(!records.TryGetValue(p.key,out var state)){state=new Expedition{key=p.key,name=p.name,anchor=ground.Focus-p.body.P};records.Add(p.key,state);Current=state;Vector3 t=PlanetExpedition.SurfaceTangent(Up(ground.Focus),game.ShipForward);Vector3 anchor=p.body.P+state.anchor;
    AddSite("RECORDER",Offset(anchor,t,-13,21));AddSite("SPECIMEN",Offset(anchor,t,13,26));AddSite("SPECIMEN",Offset(anchor,t,29,13));AddSite("SPECIMEN",Offset(anchor,t,31,36));AddSite("RELAY",Offset(anchor,t,4,45));AddSite("NEST",Offset(anchor,t,-28,69));
   }else Current=state;Attach();game.GroundNotice(Current.extracted?"Expedition complete / explore or return to the stars.":Inhabited?SurfaceEcology.SocietyName(Planet.key)+" / O mission log / take cover from armed patrols":"DISTRESS BEACON / O mission log / E interact / LMB carbine / Q shockwave");}
  }else if(wasOnFoot){if(Current!=null&&Current.core&&!Current.extracted){Current.extracted=true;game.GroundReward(1000,8);game.GroundHeal(35);game.GroundNotice("EXPEDITION EXTRACTED / +1000 score / +8 parts / crew resupplied");}Detach();Current=null;Planet=null;}
  wasOnFoot=ground.OnFoot;rifle.gameObject.SetActive(ground.OnFoot);if(!ground.OnFoot){HoldProgress=0;Prompt="";Journal=false;}
 }
 void Attach(){SurfaceScatter.Current?.Refresh();if(Inhabited)settlement.Bind(Planet,Current.anchor,game.ShipForward);root=new GameObject("EXPEDITION / "+Current.name).transform;root.SetParent(Planet.root.transform,false);foreach(var s in Current.sites){s.view=Inhabited?art.TechnologySite(root,s.kind,SurfaceEcology.For(Planet,0)):art.Site(root,s.kind,SurfaceEcology.Climate(Planet.key));s.view.localPosition=s.local;s.view.rotation=Quaternion.FromToRotation(Vector3.up,s.local.normalized);if(s.done)s.view.localScale=Vector3.one*.85f;}
  foreach(var f in Current.foes)if(!f.dead)CreateView(f);if(!Current.initialSpawned){Current.initialSpawned=true;Vector3 anchor=Planet.body.P+Current.anchor;Vector3 t=PlanetExpedition.SurfaceTangent(Up(anchor),game.ShipForward);Spawn(0,Offset(anchor,t,-21,36));Spawn(1,Offset(anchor,t,31,49));}
 }
 void Detach(){if(root!=null)Destroy(root.gameObject);root=null;if(Current!=null)foreach(var f in Current.foes){f.view=null;f.warning=null;}foreach(var a in acids)if(a.view!=null)Destroy(a.view.gameObject);acids.Clear();foreach(var e in effects)if(e.line!=null)Destroy(e.line.gameObject);effects.Clear();foreach(var p in pickups)if(p.view!=null)Destroy(p.view.gameObject);pickups.Clear();holding=null;HoldProgress=0;}
 public void ResetAll(){Detach();if(settlement!=null)settlement.Clear();records.Clear();Current=null;Planet=null;wasOnFoot=false;Ammo=24;ReloadTime=PulseCooldown=cooldown=ActiveTime=0;RifleShots=BlockedShots=Reloads=ProjectilesFired=ShotsFired=WeakHits=NativeSteps=Collected=0;Journal=false;ScriptInteract=ScriptFire=false;ScriptAim=Vector3.zero;}
 public SurfaceEcology.Species Species(Foe foe){return SurfaceEcology.For(Planet,foe.kind);}
 // Resolve the same native boulder clearance as a crew body before creating a creature view.
 public Vector3 CreaturePoint(Vector3 p){Vector3 q=GroundPoint(p,1.15f);for(int i=0;i<6;i++){if(SurfaceScatter.Current!=null)q=SurfaceScatter.Current.Clearance(q,1.15f);q=GroundPoint(q,1.15f);}return q;}
 public Foe Spawn(int kind,Vector3 p,bool relayTarget=false){if(Current==null||kind<0||kind>2||LiveCount>=10||Current.foes.Count>=20)return null;var f=new Foe{kind=kind,maxHp=SurfaceEcology.For(Planet,kind).health,relayTarget=relayTarget,cooldown=1.5f+(sequence++%4)*.4f};f.hp=f.maxHp;f.local=CreaturePoint(p)-Planet.body.P;f.maxHp*=game.ThreatHealth;f.hp=f.maxHp;Current.foes.Add(f);if(root!=null)CreateView(f);return f;}
 void CreateView(Foe f){f.view=art.Creature(root,Species(f));f.view.Contact=p=>GroundPoint(p,.075f);f.view.root.localScale=Vector3.one*(f.kind==2&&!Species(f).humanoid?1.9f:1);f.view.root.position=World(f)+Up(World(f))*(f.kind==2&&!Species(f).humanoid?1.0f:0);f.warning=NewLine("Alien attack telegraph",new Color(1,.22f,.05f),.06f);f.warning.transform.SetParent(f.view.root,false);f.warning.loop=true;f.warning.positionCount=36;f.warning.enabled=false;}
 LineRenderer NewLine(string name,Color c,float width){var l=new GameObject(name).AddComponent<LineRenderer>();l.sharedMaterial=art.BeamMaterial(c);l.startColor=l.endColor=c;l.widthMultiplier=width;l.numCapVertices=3;l.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;return l;}
 void Beam(Vector3 a,Vector3 b,Color c,float width=.055f,float life=.12f){if(effects.Count>=20){Destroy(effects[0].line.gameObject);effects.RemoveAt(0);}var l=NewLine("Carbine / fading energy trace",c,width);l.positionCount=2;l.SetPositions(new[]{a,b});effects.Add(new Effect{line=l,life=life,total=life});}
 public void Shift(Vector3 delta){if(Current!=null)foreach(var f in Current.foes){if(f.view!=null)f.view.Shift(delta);if(f.warning!=null){var p=new Vector3[f.warning.positionCount];f.warning.GetPositions(p);for(int i=0;i<p.Length;i++)p[i]-=delta;f.warning.SetPositions(p);}}foreach(var a in acids){a.state.x-=delta.x;a.state.y-=delta.y;a.state.z-=delta.z;if(a.view!=null)a.view.position-=delta;}foreach(var e in effects){var points=new Vector3[e.line.positionCount];e.line.GetPositions(points);for(int i=0;i<points.Length;i++)points[i]-=delta;e.line.SetPositions(points);}}
 public void Tick(float dt,bool active){Sync();if(Current==null)return;
  // Visuals follow aim even during pause; all encounter and weapon timers use gameplay time.
  Vector3 up=Up(ground.Focus);Vector3 aim=Scripted&&ScriptAim.sqrMagnitude>.1f?(ScriptAim-camera.transform.position).normalized:camera.transform.forward;
  ground.CombatPose(true,ReloadTime,HoldProgress>0,aim,Scripted?ScriptFire:game.CrewFire||game.CrewAim);rifle.position=ground.Motion!=null?ground.Motion.Grip.position+aim*.10f:ground.Focus+up*.16f+Vector3.Cross(up,aim).normalized*.43f+aim*.38f;rifle.rotation=Quaternion.LookRotation(aim,up)*Quaternion.Euler(0,0,ReloadTime>0?Mathf.Sin((1-ReloadTime/1.45f)*Mathf.PI)*-28:0);rifle.position-=aim*recoil*.09f;
  if(!active)return;ActiveTime+=dt;cooldown=Mathf.Max(0,cooldown-dt);hitMark=Mathf.Max(0,hitMark-dt);recoil=Mathf.Max(0,recoil-dt*9);PulseCooldown=Mathf.Max(0,PulseCooldown-dt);pulseVisual=Mathf.Max(0,pulseVisual-dt);
  if(ReloadTime>0){ReloadTime=Mathf.Max(0,ReloadTime-dt);if(ReloadTime==0)Ammo=24;}
  if(!Scripted){if(game.CrewReload)Reload();if(game.CrewPulse)Pulse();if(!game.GroundFireBlocked&&game.CrewFire)Shoot(camera.transform.position,camera.transform.forward);}
  else if(ScriptFire)Shoot(camera.transform.position,aim);
  Interact(Scripted?ScriptInteract:game.CrewInteract,dt);
  for(int i=effects.Count-1;i>=0;i--){var e=effects[i];e.life-=dt;e.line.widthMultiplier=.055f*Mathf.Max(0,e.life/e.total);if(e.life<=0){Destroy(e.line.gameObject);effects.RemoveAt(i);}}
 }
 public Transform Weapon{get{return rifle;}}
 public void LatePose(){if(Current==null||ground.Motion==null)return;Vector3 up=Up(ground.Focus),aim=Scripted&&ScriptAim.sqrMagnitude>.1f?(ScriptAim-camera.transform.position).normalized:camera.transform.forward;rifle.position=ground.Motion.Grip.position+aim*.10f-aim*recoil*.09f;rifle.rotation=Quaternion.LookRotation(aim,up)*Quaternion.Euler(0,0,ReloadTime>0?Mathf.Sin((1-ReloadTime/1.45f)*Mathf.PI)*-28:0);}
 public void Reload(){if(ReloadTime>0||Ammo==24)return;ReloadTime=1.45f;game.GroundNotice("RELOADING / 1.45s");}
 public float RayLimit(Vector3 origin,Vector3 direction,float length){direction.Normalize();for(float d=.4f;d<length;d+=.45f)if(ground.Alt(origin+direction*d)<.08f)return Mathf.Max(0,d-.45f);return length;}
 public bool Shoot(Vector3 origin,Vector3 direction){if(Current==null||cooldown>0||ReloadTime>0)return false;if(Ammo==0){Reload();return false;}Ammo--;ShotsFired++;cooldown=.145f;recoil=1;ground.Recoil();Sound(laserClip);direction=game.AssistedAim(origin,direction,true);direction.Normalize();float length=RayLimit(origin,direction,100),near=length;Foe target=null;bool weak=false;
  foreach(var f in Current.foes){if(f.dead)continue;if(Species(f).humanoid){if(HumanRayHit(f,origin,direction,near,out float hit,out bool head)){near=hit;target=f;weak=head;}continue;}Vector3 center=World(f)+Up(World(f))*(f.kind==2&&!Species(f).humanoid?1.3f:.12f),offset=center-origin;float t=Vector3.Dot(offset,direction),radius=Species(f).humanoid?.65f:f.kind==2?2.1f:1.05f;if(t<=0||t>=near||Vector3.Cross(offset,direction).magnitude>radius)continue;near=t;target=f;weak=Vector3.Dot(origin-center,f.view!=null?f.view.root.forward:-direction)>.05f&&Vector3.Dot(origin+direction*t-center,Up(center))>.12f;}
  Vector3 end=origin+direction*near;Vector3 muzzle=rifle.position+direction*.8f;Vector3 barrelRay=end-muzzle;float cover=RayLimit(muzzle,barrelRay.normalized,barrelRay.magnitude);if(cover<barrelRay.magnitude-.55f){end=muzzle+barrelRay.normalized*cover;target=null;}Beam(muzzle,end,new Color(.25f,1,1));
  if(target!=null){float damage=target.kind==2?21:28;if(weak){damage*=1.6f;WeakHits++;}Damage(target,damage);hitMark=.18f;Sound(hitClip,.8f);}return true;
 }
 public void Damage(Foe f,float amount){if(f.dead)return;f.hp=Mathf.Max(0,f.hp-amount);f.hurt=.18f;if(Species(f).humanoid)f.stun=Mathf.Max(f.stun,.10f);if(f.hp>0)return;f.dead=true;Current.kills++;if(!f.rewarded){f.rewarded=true;game.GroundReward(f.kind==2?500:75,f.kind==2?4:1);Drop(World(f));}if(f.kind==2)game.GroundNotice(Species(f).name+(Inhabited?" DEFEATED / recover the command cipher":" DEFEATED / recover the brood core at the nest"));}
 void Drop(Vector3 p){if(pickups.Count>=12)return;var t=art.Piece("Field medgel / approach to restore 18 health",root,PrimitiveType.Cube,Vector3.zero,Vector3.one*.35f,art.cyan);Vector3 local=GroundPoint(p,.5f)-Planet.body.P;t.localPosition=local;pickups.Add(new Pickup{local=local,view=t});}
 public void Pulse(){if(Current==null||PulseCooldown>0)return;PulseCooldown=8;pulseVisual=.5f;Sound(pulseClip);foreach(var f in Current.foes)if(!f.dead&&Vector3.Distance(World(f),ground.Focus)<9){Damage(f,f.kind==2?35:44);f.stun=2;f.attacking=false;f.windup=0;f.burst=0;}
  Vector3 up=Up(ground.Focus),t=PlanetExpedition.SurfaceTangent(up,Vector3.forward),s=Vector3.Cross(up,t);var l=NewLine("Suit shockwave",new Color(.1f,.9f,1),.12f);l.loop=true;l.positionCount=64;for(int i=0;i<64;i++){float a=i*Mathf.PI/32;l.SetPosition(i,ground.Focus+up*.1f+(t*Mathf.Cos(a)+s*Mathf.Sin(a))*8);}effects.Add(new Effect{line=l,life=.45f,total=.45f});game.GroundNotice("SHOCKWAVE / nearby creatures stunned / 8s recharge");}
 public Site Objective {get {if(Current==null)return null;if(!Current.recorder)return Current.sites[0];if(Current.scans<3){Site best=null;float d=float.MaxValue;foreach(var s in Current.sites)if(s.kind=="SPECIMEN"&&!s.done){float n=(World(s)-ground.Focus).sqrMagnitude;if(n<d){d=n;best=s;}}return best;}if(!Current.relay)return Current.sites[4];if(!Current.core)return Current.sites[5];return null;}}
 bool CanUse(Site s,out string reason){reason="";if(s.done){reason="DATA SECURED";return false;}if(s.kind=="SPECIMEN"&&!Current.recorder){reason=(Inhabited?"Recover the security log first":"Recover the flight recorder first");return false;}if(s.kind=="RELAY"&&(!Current.recorder||Current.scans<3)){reason=(Inhabited?"Relay locked / recover security log and decrypt 3 archives":"Relay locked / recover recorder and scan 3 specimens");return false;}if(s.kind=="RELAY"&&Current.defending){reason="DEFEND RELAY / stay within 24m";return false;}if(s.kind=="NEST"){if(!Current.relay){reason=(Inhabited?"Command server sealed / complete relay uplink":"Nest sealed / complete relay uplink");return false;}foreach(var f in Current.foes)if(f.kind==2&&!f.dead){reason="Defeat the "+SurfaceEcology.For(Planet,2).name;return false;}if(!Current.bossSpawned){reason=(Inhabited?"Approach command / armed commander detected":"Approach the nest / Warden detected");return false;}}return true;}
 public void Interact(bool held,float dt){Prompt="";Site nearest=null;float distance=4.4f;foreach(var s in Current.sites){float d=Vector3.Distance(ground.Focus,World(s)+Up(World(s))*.8f);if(d<distance){nearest=s;distance=d;}}
  if(nearest==null){holding=null;HoldProgress=0;return;}bool usable=CanUse(nearest,out string reason);Prompt=usable?"HOLD E / "+(nearest.kind=="SPECIMEN"?(Inhabited?"DECRYPT ARCHIVE":"SCAN SPECIMEN"):nearest.kind=="RECORDER"?(Inhabited?"RECOVER SECURITY LOG":"RECOVER FLIGHT RECORDER"):nearest.kind=="RELAY"?"RESTART & DEFEND RELAY":Inhabited?"RECOVER COMMAND CIPHER":"RECOVER BROOD CORE"):reason;
  Vector3 target=World(nearest)+Up(World(nearest))*.9f;bool visible=RayLimit(ground.Focus+Up(ground.Focus)*.45f,(target-ground.Focus).normalized,distance)>=distance-.9f;
  if(!usable||!held||!visible){holding=null;HoldProgress=0;return;}if(holding!=nearest){holding=nearest;HoldProgress=0;}HoldProgress+=dt/(nearest.kind=="SPECIMEN"?1.8f:1.3f);if(HoldProgress<1)return;HoldProgress=0;holding=null;
  if(nearest.kind=="RELAY"){Current.defending=true;Current.defense=0;Current.wave=0;Current.relayHealth=100;game.GroundNotice("UPLINK STARTED / defend the relay for 24 seconds");return;}
  nearest.done=true;if(nearest.kind=="RECORDER"){Current.recorder=true;game.GroundReward(250,2);game.GroundNotice((Inhabited?"SECURITY LOG SECURED / +250 / decrypt three research archives":"FLIGHT RECORDER SECURED / +250 / scan three alien specimens"));}else if(nearest.kind=="SPECIMEN"){Current.scans++;game.GroundReward(150,1);game.GroundNotice((Inhabited?"ARCHIVE ":"SPECIMEN ")+Current.scans+" / 3 SECURED / +150");}else{Current.core=true;game.GroundReward(400,3);game.GroundNotice((Inhabited?"COMMAND CIPHER SECURED / return to your ship and press J to extract":"BROOD CORE SECURED / return to your ship and press J to extract"));}Sound(pulseClip,.45f);
 }
 public void Step(float dt){if(Current==null||!ground.OnFoot)return;Current.age+=dt;var relay=Current.sites[4];
  if(Current.relay&&!Current.bossSpawned&&Vector3.Distance(ground.Focus,World(Current.sites[5]))<32){var boss=Spawn(2,World(Current.sites[5])+PlanetExpedition.SurfaceTangent(Up(ground.Focus),game.ShipForward)*4);if(boss!=null){Current.bossSpawned=true;game.GroundNotice(Species(boss).name+(Inhabited?" / armored security commander / use cover and Q pulse":" / exposed organs take extra damage / Q staggers nearby foes"));Sound(alertClip);}}
  if(Current.defending){if(Current.relayHealth<=0){Current.defending=false;game.GroundNotice("UPLINK LOST / clear the hostiles, hold E at the relay to retry");}else if(Vector3.Distance(ground.Focus,World(relay))<24){Current.defense+=dt;if(Current.wave<game.RelayWaves&&Current.defense>=Current.wave*8){int wave=Current.wave++;Vector3 t=PlanetExpedition.SurfaceTangent(Up(World(relay)),game.ShipForward);Spawn(wave==1?1:0,Offset(World(relay),t,-14-wave*2,13),true);Spawn(wave==2?1:0,Offset(World(relay),t,15,-12-wave),true);Sound(alertClip,.6f);}if(Current.defense>=game.RelayDuration){Current.defending=false;Current.relay=true;relay.done=true;game.GroundReward(400,3);game.GroundHeal(25);game.GroundNotice((Inhabited?"RELAY ONLINE / +400 / command server located":"RELAY ONLINE / +400 / suit repaired / Warden nest located"));}}}
  // Ambient patrols are finite: an expedition is clearable, including when revisited.
  for(int i=Current.foes.Count-1;i>=0;i--){var f=Current.foes[i];if(f.dead){f.deadAge+=dt;if(f.view!=null){f.view.Animate(Current.age,0,0,0,true);if(f.deadAge>5){Destroy(f.view.root.gameObject);f.view=null;}}if(f.deadAge>5)Current.foes.RemoveAt(i);continue;}
