 void AcidShot(Vector3 p,Vector3 target,SurfaceEcology.Species species){
  if(acids.Count>=24)return;ProjectilesFired++;float speed=species.biome==SurfaceEcology.Biome.Arid?16:species.biome==SurfaceEcology.Biome.Frozen?10:12;
