  var t=art.Piece(species.name+" / native ballistic projectile",root,PrimitiveType.Sphere,Vector3.zero,Vector3.one*(species.biome==SurfaceEcology.Biome.Frozen?.36f:.25f),art.BeamMaterial(species.organ));
  t.position=p;acids.Add(new Acid{view=t,damage=species.damage,state=new OrbitDemo.State{x=p.x,y=p.y,z=p.z,vx=v.x,vy=v.y,vz=v.z}});
